#!/usr/bin/env node
// Adds release signing to the Android project generated by `tauri android init`.
//
// The keystore and its passwords are read from environment variables at Gradle
// build time, so no secret is ever written into the project:
//
//   SECCOM_ANDROID_KEYSTORE           absolute path to the .jks / .keystore file
//   SECCOM_ANDROID_KEYSTORE_PASSWORD  keystore password
//   SECCOM_ANDROID_KEY_ALIAS          key alias
//   SECCOM_ANDROID_KEY_PASSWORD       key password (defaults to the keystore password)
//
// Without SECCOM_ANDROID_KEYSTORE the release build stays unsigned.
// The script is idempotent: running it again changes nothing.
//
// Usage: node build/android/configure-gradle.mjs <path to gen/android>

import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const MARKER = "SECCOM_ANDROID_KEYSTORE";

const genDir = process.argv[2];
if (!genDir) {
  console.error("usage: configure-gradle.mjs <app/src-tauri/gen/android>");
  process.exit(2);
}

const gradleFile = join(genDir, "app", "build.gradle.kts");
if (!existsSync(gradleFile)) {
  console.error(`error: ${gradleFile} not found — run "npx tauri android init" first`);
  process.exit(1);
}

let text = readFileSync(gradleFile, "utf8");
if (text.includes(MARKER)) {
  console.log("release signing is already configured");
} else {
  function insertBefore(source, anchor, snippet) {
    const at = source.indexOf(anchor);
    if (at < 0) throw new Error(`cannot find "${anchor.trim()}" in ${gradleFile}`);
    return source.slice(0, at) + snippet + source.slice(at);
  }

  function insertAfter(source, anchor, snippet) {
    const at = source.indexOf(anchor);
    if (at < 0) throw new Error(`cannot find "${anchor.trim()}" in ${gradleFile}`);
    const end = at + anchor.length;
    return source.slice(0, end) + snippet + source.slice(end);
  }

  try {
    text = insertBefore(
      text,
      "android {",
      `// SecCorp: release signing from environment variables (no secrets on disk).
val seccomKeystore: String? = System.getenv("${MARKER}")

`,
    );
    text = insertBefore(
      text,
      "    buildTypes {",
      `    signingConfigs {
        create("release") {
            seccomKeystore?.let { keystore ->
                storeFile = file(keystore)
                storePassword = System.getenv("SECCOM_ANDROID_KEYSTORE_PASSWORD")
                keyAlias = System.getenv("SECCOM_ANDROID_KEY_ALIAS")
                keyPassword = System.getenv("SECCOM_ANDROID_KEY_PASSWORD")
                    ?: System.getenv("SECCOM_ANDROID_KEYSTORE_PASSWORD")
            }
        }
    }
`,
    );
    text = insertAfter(
      text,
      'getByName("release") {',
      `
            if (seccomKeystore != null) {
                signingConfig = signingConfigs.getByName("release")
            }`,
    );
  } catch (e) {
    console.error(`error: ${e.message}`);
    console.error("The generated Gradle file has an unexpected layout; add signing manually (see README).");
    process.exit(1);
  }

  writeFileSync(gradleFile, text);
  console.log(`release signing added to ${gradleFile}`);
}

// Use the generated round launcher asset on launchers that support it.
const manifestFile = join(genDir, "app", "src", "main", "AndroidManifest.xml");
let manifest = readFileSync(manifestFile, "utf8");
if (!manifest.includes("android:roundIcon=")) {
  manifest = manifest.replace(
    '        android:icon="@mipmap/ic_launcher"',
    '        android:icon="@mipmap/ic_launcher"\n        android:roundIcon="@mipmap/ic_launcher_round"',
  );
  writeFileSync(manifestFile, manifest);
  console.log(`round launcher icon added to ${manifestFile}`);
}
